import React from 'react';

import type { LoopEffect } from './../ricos-schema/next-schema/index.js';
import {
  Animation_Orientation,
  Animation_SideDirection,
  LoopEffect_Breathe_Direction,
} from './../ricos-schema/next-schema/index.js';
import type { LogBiFn } from './../_shared/bi-context-provider/bi-context-provider.js';
import { defaultLoopEasingOf, LOOP_EFFECTS } from './../_shared/node-animation/loop-effects.js';

import type { EffectParamControls } from './effect-controls.js';
import {
  directionSelect,
  FOUR_SIDES,
  MotionStyleField,
  ParamControlField,
  spinDirectionToggle,
} from './effect-controls.js';

/**
 * The control each loop effect's param renders as — the loop twin of
 * `EFFECT_PARAM_CONTROL`, following the same rules: options derive from the schema's own
 * enums, one categorical param per effect, and effects absent here (RUBBER, PULSE, WIGGLE,
 * BOUNCE, JELLO, FLASH) expose no param at all.
 */
export const LOOP_EFFECT_PARAM_CONTROL: EffectParamControls<LoopEffect> = {
  BREATHE: directionSelect(Object.values(LoopEffect_Breathe_Direction)),
  // Cross drifts *toward* its direction (re-entering from the opposite side) and Poke nudges
  // *toward* it, so both are labelled and arrowed as the opposite side — see `displayValueOf`.
  CROSS: directionSelect(Object.values(Animation_SideDirection), 'destination'),
  FLIP: directionSelect(Object.values(Animation_Orientation)),
  FOLD: directionSelect(FOUR_SIDES),
  POKE: directionSelect(FOUR_SIDES, 'destination'),
  SWING: directionSelect(FOUR_SIDES),
  SPIN: spinDirectionToggle,
};

type Props = {
  effect: LoopEffect;
  onChange: (effect: LoopEffect) => void;
  logBi: LogBiFn;
};

/**
 * Every control backed by a property of the `LoopEffect` itself. The envelope's own settings
 * (duration, delay between loops) stay with the panel, so the split here mirrors the schema.
 */
export const LoopEffectControls: React.FC<Props> = ({ effect, onChange, logBi }) => (
  <>
    <ParamControlField
      effect={effect}
      onChange={onChange}
      logBi={logBi}
      control={LOOP_EFFECT_PARAM_CONTROL[effect.type]}
      defaults={LOOP_EFFECTS[effect.type].params as Record<string, unknown> | undefined}
    />
    <MotionStyleField
      effect={effect}
      onChange={onChange}
      logBi={logBi}
      defaultEasing={defaultLoopEasingOf(effect.type)}
    />
  </>
);
