import { FormField, SegmentedToggle } from '@wix/design-system';
import React, { useContext } from 'react';

import { RicosContext, ZIndexContext } from './../ricos-context/index.js';
import type { EntranceEffect } from './../ricos-schema/next-schema/index.js';
// The enum consts double as their own types, so `Animation_Easing` below is both.
import {
  Animation_CornerDirection,
  Animation_Direction,
  Animation_Easing,
  Animation_Orientation,
  Animation_RadialDirection,
  Animation_SideDirection,
  Animation_SpinDirection,
  EntranceEffect_Bounce_Direction,
  EntranceEffect_Glide_Direction,
  EntranceEffect_Shape_ClipShape,
} from './../ricos-schema/next-schema/index.js';
import type { LogBiFn } from './../_shared/bi-context-provider/bi-context-provider.js';
import { defaultEasingOf, ENTRANCE_EFFECTS } from './../_shared/node-animation/entrance-effects.js';
import {
  RadioGroupWithLabel,
  SelectWithLabel,
  ThumbnailPicker,
  usePanelContainerElement,
} from './../ui-components/index.js';

import classes from './animation-panel-scss.js';
import { ANIMATION_PANEL_BUTTONS } from './data-hooks.js';
import { DIRECTION_ICONS } from './icons/direction-icons.js';
import { SHAPE_ICONS } from './icons/shape-icons.js';

const DIRECTION_LABEL_KEY = 'AnimationPanel_Direction_Label';

const OPTION_LABEL_KEYS: Record<string, string> = {
  TOP: 'AnimationPanel_Direction_Top',
  RIGHT: 'AnimationPanel_Direction_Right',
  BOTTOM: 'AnimationPanel_Direction_Bottom',
  LEFT: 'AnimationPanel_Direction_Left',
  CENTER: 'AnimationPanel_Direction_Center',
  TOP_LEFT: 'AnimationPanel_Direction_TopLeft',
  TOP_RIGHT: 'AnimationPanel_Direction_TopRight',
  BOTTOM_LEFT: 'AnimationPanel_Direction_BottomLeft',
  BOTTOM_RIGHT: 'AnimationPanel_Direction_BottomRight',
  HORIZONTAL: 'AnimationPanel_Direction_Horizontal',
  VERTICAL: 'AnimationPanel_Direction_Vertical',
  // SWIVEL's pivot enum spells the same two axes CENTER_* — one vocabulary, both spellings
  CENTER_HORIZONTAL: 'AnimationPanel_Direction_Horizontal',
  CENTER_VERTICAL: 'AnimationPanel_Direction_Vertical',
  CLOCKWISE: 'AnimationPanel_Direction_Clockwise',
  COUNTER_CLOCKWISE: 'AnimationPanel_Direction_CounterClockwise',
  CIRCLE: 'AnimationPanel_Shape_Circle',
  ELLIPSE: 'AnimationPanel_Shape_Ellipse',
  RECTANGLE: 'AnimationPanel_Shape_Rectangle',
  DIAMOND: 'AnimationPanel_Shape_Diamond',
};

// The maps above are written in entrance vocabulary: the label names the side the element comes
// *from*, and DIRECTION_ICONS points its arrow away from the side it's keyed by (the way the
// element travels). An effect whose `direction` instead names where the element *heads* — CROSS
// drifts toward a side, POKE nudges toward one — would therefore render both halves inverted.
// Looking such a value up as its opposite side corrects label and arrow in one step:
// `OPTION_LABEL_KEYS[opposite]` reads "From <opposite>" (true for CROSS, which really does
// re-enter from there), and the arrow lands back on the actual destination.
const OPPOSITE_SIDE: Record<string, string> = {
  LEFT: 'RIGHT',
  RIGHT: 'LEFT',
  TOP: 'BOTTOM',
  BOTTOM: 'TOP',
};

/** What an effect's stored `direction` names: where the element comes from, or where it heads. */
export type DirectionSemantics = 'origin' | 'destination';

/** Any effect variant: a discriminant plus its own optional params. */
type AnyEffect = { type: string };

/**
 * The categorical params a control may write for one effect variant: its own string-valued
 * fields, minus the discriminant and `easing` (motion style has its own control).
 */
type ParamKeyOf<V> = {
  [K in Exclude<keyof V, 'type' | 'easing'>]-?: NonNullable<V[K]> extends string ? K : never;
}[Exclude<keyof V, 'type' | 'easing'>] &
  // schema variants only ever declare string keys; this just satisfies `K extends string`
  string;

/**
 * A family's control map, with each entry's `key` narrowed to the params that effect's own
 * schema variant declares — so a typo, or a key borrowed from a sibling effect, fails to compile
 * rather than rendering an empty control and writing junk onto the effect.
 */
export type EffectParamControls<E extends AnyEffect> = {
  [T in E['type']]?: ParamControl<ParamKeyOf<Extract<E, { type: T }>>>;
};

/**
 * Where a control sits among the fields the panel renders around it. The pointer panel's fixed
 * order is: Mouse movement → `top` → Motion style → `middle` → Velocity → `end`. Velocity belongs
 * to the envelope and so stays with the panel — which is why `end` is a slot rather than just
 * "last child".
 */
export type ControlSlot = 'top' | 'middle' | 'end';

/**
 * `EffectParamControls` for a family whose effects may expose a control in more than one slot,
 * with the same per-effect key narrowing: a key borrowed from a sibling effect still fails to
 * compile rather than writing junk onto the effect.
 */
export type SlottedParamControls<E extends AnyEffect> = {
  [T in E['type']]?: { [S in ControlSlot]?: ParamControl<ParamKeyOf<Extract<E, { type: T }>>> };
};

type BaseParamControl<K extends string> = {
  key: K;
  labelKey: string;
  options: string[];
  /**
   * Overrides the shared direction/shape vocabulary, for the values it doesn't name — the
   * movement axis's "Both", Resize's "Expand"/"Shrink".
   */
  optionLabelKeys?: Record<string, string>;
};

export type ParamControl<K extends string = string> =
  | (BaseParamControl<K> & {
      kind: 'select';
      /** Only the `direction` params have an origin/destination reading — see OPPOSITE_SIDE. */
      semantics?: DirectionSemantics;
    })
  | (BaseParamControl<K> & {
      kind: 'segmented';
      /** Words instead of glyphs, for the params with no arrow to draw (Expand/Shrink). */
      labels?: 'icons' | 'text';
    })
  | (BaseParamControl<K> & { kind: 'thumbnails' });

/** The side a stored value is labelled and iconed as — see OPPOSITE_SIDE. */
export const displayValueOf = (control: ParamControl, option: string): string =>
  'semantics' in control && control.semantics === 'destination'
    ? (OPPOSITE_SIDE[option] ?? option)
    : option;

/** The control's own override, else the shared direction/shape vocabulary. */
export const labelKeyOf = (control: ParamControl, option: string): string =>
  control.optionLabelKeys?.[option] ?? OPTION_LABEL_KEYS[displayValueOf(control, option)];

// Options come from the schema's own enums rather than a hand-kept list, so a value added to
// (or removed from) an effect's param can't leave the dropdown stale. The JTD declares them in
// Harmony's effects-kit order, which is also the order the panel should offer them in.
export const directionSelect = (
  options: string[],
  semantics: DirectionSemantics = 'origin'
): ParamControl<'direction'> => ({
  kind: 'select',
  key: 'direction',
  labelKey: DIRECTION_LABEL_KEY,
  options,
  semantics,
});

export const spinDirectionToggle: ParamControl<'direction'> = {
  kind: 'segmented',
  key: 'direction',
  labelKey: DIRECTION_LABEL_KEY,
  options: Object.values(Animation_SpinDirection),
};

export const FOUR_SIDES = Object.values(Animation_Direction);

/**
 * The control each entrance effect's param renders as, mirroring Harmony's
 * motion-effects-panels. v1 exposes one param per effect; numeric tuning params (distance,
 * spins, shutters) stay on motion's tuned defaults and can be added later with no data change.
 *
 * The pre-selected value comes from `ENTRANCE_EFFECTS` — the same map that feeds playback — so
 * the control can never disagree with what actually plays. Effects absent from this map
 * (FADE, BLUR, DROP) expose no param at all.
 */
export const EFFECT_PARAM_CONTROL: EffectParamControls<EntranceEffect> = {
  ARC: directionSelect(FOUR_SIDES),
  BOUNCE: directionSelect(Object.values(EntranceEffect_Bounce_Direction)),
  EXPAND: directionSelect(Object.values(Animation_RadialDirection)),
  FLIP: directionSelect(FOUR_SIDES),
  FLOAT: directionSelect(FOUR_SIDES),
  FOLD: directionSelect(FOUR_SIDES),
  GLIDE: directionSelect(Object.values(EntranceEffect_Glide_Direction)),
  REVEAL: directionSelect(FOUR_SIDES),
  SHUTTERS: directionSelect(FOUR_SIDES),
  SLIDE: directionSelect(FOUR_SIDES),
  TILT: directionSelect(Object.values(Animation_SideDirection)),
  TURN: directionSelect(Object.values(Animation_CornerDirection)),
  WINK: directionSelect(Object.values(Animation_Orientation)),
  SPIN: spinDirectionToggle,
  SHAPE: {
    kind: 'thumbnails',
    key: 'shape',
    labelKey: 'AnimationPanel_Shape_Label',
    options: Object.values(EntranceEffect_Shape_ClipShape),
  },
};

const MOTION_STYLE_OPTIONS = Object.values(Animation_Easing);

const MOTION_STYLE_LABEL_KEYS: Record<Animation_Easing, string> = {
  GENTLE: 'AnimationPanel_MotionStyle_Gentle',
  MODERATE: 'AnimationPanel_MotionStyle_Moderate',
  INTENSE: 'AnimationPanel_MotionStyle_Intense',
};

type FieldProps<E extends AnyEffect> = {
  effect: E;
  onChange: (effect: E) => void;
  logBi: LogBiFn;
};

/**
 * The single categorical param an effect exposes, if any — family-agnostic: the entrance
 * and loop wrappers below pass their own control map entry and defaults, both derived from
 * the family's config map so the control can never disagree with what actually plays.
 */
export const ParamControlField = <E extends AnyEffect>({
  effect,
  onChange,
  logBi,
  control,
  defaults,
}: FieldProps<E> & {
  control: ParamControl | undefined;
  defaults: Record<string, unknown> | undefined;
}) => {
  const { t } = useContext(RicosContext);
  const zIndexService = useContext(ZIndexContext);
  const containerEl = usePanelContainerElement();

  if (!control) {
    return null;
  }

  const stored = (effect as unknown as Record<string, unknown>)[control.key];
  const value = stored ?? defaults?.[control.key];
  const label = t(control.labelKey);

  const patch = (next: unknown) => onChange({ ...effect, [control.key]: next } as E);

  if (control.kind === 'segmented') {
    const asText = control.labels === 'text';

    return (
      <FormField label={label}>
        <SegmentedToggle
          selected={value as string}
          // WDS fires onClick on the already-selected segment too; re-writing the same
          // value would log a BI event and push a no-op document change (an undo step)
          onClick={(_, option: string) => {
            if (option === value) {
              return;
            }
            logBi?.({ dataHook: ANIMATION_PANEL_BUTTONS.paramToggle(control.key), value: option });
            patch(option);
          }}
          size="small"
          fullWidth
          dataHook={ANIMATION_PANEL_BUTTONS.paramToggle(control.key)}
        >
          {control.options.map(option =>
            asText ? (
              <SegmentedToggle.Button
                key={option}
                value={option}
                dataHook={ANIMATION_PANEL_BUTTONS.paramToggleOption(option)}
              >
                {t(labelKeyOf(control, option))}
              </SegmentedToggle.Button>
            ) : (
              <SegmentedToggle.Icon
                key={option}
                value={option}
                tooltipText={t(labelKeyOf(control, option))}
                tooltipProps={{ appendTo: containerEl }}
                dataHook={ANIMATION_PANEL_BUTTONS.paramToggleOption(option)}
              >
                {DIRECTION_ICONS[displayValueOf(control, option)]}
              </SegmentedToggle.Icon>
            )
          )}
        </SegmentedToggle>
      </FormField>
    );
  }

  if (control.kind === 'thumbnails') {
    return (
      <div className={classes.shapePicker}>
        <ThumbnailPicker
          title={label}
          selectedValue={value as string}
          onChange={patch}
          // bare shapes with no captions, matching Harmony's ShapeThumbnails — passing a
          // `label` would render a caption under each thumb, which the spec doesn't have
          dataSource={control.options.map(option => ({
            value: option,
            dataHook: ANIMATION_PANEL_BUTTONS.paramThumbnail(option),
            renderBackgroundImage: SHAPE_ICONS[option as keyof typeof SHAPE_ICONS],
          }))}
          tooltipAppendTo={containerEl}
          dataHook={ANIMATION_PANEL_BUTTONS.paramThumbnails}
          logBi={logBi}
        />
      </div>
    );
  }

  return (
    <SelectWithLabel
      label={label}
      dataHook={ANIMATION_PANEL_BUTTONS.param}
      value={value as string}
      // `id` stays the value the schema stores; only the label and arrow may be flipped
      options={control.options.map(option => ({
        id: option,
        value: t(labelKeyOf(control, option)),
        icon: DIRECTION_ICONS[displayValueOf(control, option)],
      }))}
      onChange={patch}
      logBi={logBi}
      zIndex={zIndexService.getZIndex('DIALOG')}
      // "From bottom right" doesn't fit the compact side-by-side layout
      legendPlacement="top"
    />
  );
};

/**
 * Motion style — family-agnostic: only rendered when the family's config map yields a
 * default for the effect, i.e. exactly when its schema variant declares `easing`.
 */
export const MotionStyleField = <E extends AnyEffect>({
  effect,
  onChange,
  logBi,
  defaultEasing,
}: FieldProps<E> & { defaultEasing: Animation_Easing | undefined }) => {
  const { t } = useContext(RicosContext);

  if (!defaultEasing) {
    return null;
  }

  return (
    <RadioGroupWithLabel
      label={t('AnimationPanel_MotionStyle_Label')}
      dataHook={ANIMATION_PANEL_BUTTONS.motionStyle}
      // omit-until-touched: shows the effect's default, but the document only
      // stores easing once the user actually picks an option
      value={(effect as { easing?: Animation_Easing }).easing ?? defaultEasing}
      options={MOTION_STYLE_OPTIONS.map(style => ({
        id: style,
        value: t(MOTION_STYLE_LABEL_KEYS[style]),
      }))}
      onChange={easing => onChange({ ...effect, easing } as E)}
      logBi={logBi}
    />
  );
};

type Props = {
  effect: EntranceEffect;
  onChange: (effect: EntranceEffect) => void;
  logBi: LogBiFn;
};

/**
 * Every control backed by a property of the `EntranceEffect` itself. The envelope's own settings
 * (duration, delay) stay with the panel, so the split here mirrors the schema.
 *
 * Order follows Harmony's motion-effects-panels: the effect's own param, then motion style.
 */
export const EffectControls: React.FC<Props> = ({ effect, onChange, logBi }) => (
  <>
    <ParamControlField
      effect={effect}
      onChange={onChange}
      logBi={logBi}
      control={EFFECT_PARAM_CONTROL[effect.type]}
      defaults={ENTRANCE_EFFECTS[effect.type].params as Record<string, unknown> | undefined}
    />
    <MotionStyleField
      effect={effect}
      onChange={onChange}
      logBi={logBi}
      defaultEasing={defaultEasingOf(effect.type)}
    />
  </>
);
