const NONE = 'NONE';

// Harmony's hover-preview delay (motion-effects-panels AnimationThumbnail)
const HOVER_PREVIEW_DELAY = 200;

// UI labels are not schema names — DROP renders as "Shrink" (see adr/004)
const EFFECT_LABEL_KEYS: Record<EntranceEffect_Type, string> = {
  FADE: 'AnimationPanel_Effect_Fade',
  ARC: 'AnimationPanel_Effect_Arc',
  BLUR: 'AnimationPanel_Effect_Blur',
  BOUNCE: 'AnimationPanel_Effect_Bounce',
  DROP: 'AnimationPanel_Effect_Shrink',
  EXPAND: 'AnimationPanel_Effect_Expand',
  FLIP: 'AnimationPanel_Effect_Flip',
  FLOAT: 'AnimationPanel_Effect_Float',
  FOLD: 'AnimationPanel_Effect_Fold',
  GLIDE: 'AnimationPanel_Effect_Glide',
  REVEAL: 'AnimationPanel_Effect_Reveal',
  SHAPE: 'AnimationPanel_Effect_Shape',
  SHUTTERS: 'AnimationPanel_Effect_Shutters',
  SLIDE: 'AnimationPanel_Effect_Slide',
  SPIN: 'AnimationPanel_Effect_Spin',
  TILT: 'AnimationPanel_Effect_Tilt',
  TURN: 'AnimationPanel_Effect_Turn',
  WINK: 'AnimationPanel_Effect_Wink',
};

// RUBBER renders as "Rubber band" — same UI-label ≠ schema-name divergence as DROP/"Shrink"
const LOOP_EFFECT_LABEL_KEYS: Record<LoopEffect_Type, string> = {
  BOUNCE: 'AnimationPanel_LoopEffect_Bounce',
  BREATHE: 'AnimationPanel_LoopEffect_Breathe',
  CROSS: 'AnimationPanel_LoopEffect_Cross',
  FLASH: 'AnimationPanel_LoopEffect_Flash',
  FLIP: 'AnimationPanel_LoopEffect_Flip',
  FOLD: 'AnimationPanel_LoopEffect_Fold',
  JELLO: 'AnimationPanel_LoopEffect_Jello',
  POKE: 'AnimationPanel_LoopEffect_Poke',
  PULSE: 'AnimationPanel_LoopEffect_Pulse',
  RUBBER: 'AnimationPanel_LoopEffect_Rubber',
  SPIN: 'AnimationPanel_LoopEffect_Spin',
  SWING: 'AnimationPanel_LoopEffect_Swing',
  WIGGLE: 'AnimationPanel_LoopEffect_Wiggle',
};

// "Resize" is SCALE (motion ScaleMouse) and "Skew 3D" is SKEW — same UI-label ≠
// schema-name divergence as DROP/"Shrink"
const POINTER_EFFECT_LABEL_KEYS: Record<PointerEffect_Type, string> = {
  AIRY: 'AnimationPanel_MouseEffect_Airy',
  BLOB: 'AnimationPanel_MouseEffect_Blob',
  BLUR: 'AnimationPanel_MouseEffect_Blur',
  SCALE: 'AnimationPanel_MouseEffect_Resize',
  SKEW: 'AnimationPanel_MouseEffect_Skew3d',
  SWIVEL: 'AnimationPanel_MouseEffect_Swivel',
  TILT_3D: 'AnimationPanel_MouseEffect_Tilt3d',
  TRACK: 'AnimationPanel_MouseEffect_Track',
  TRACK_3D: 'AnimationPanel_MouseEffect_Track3d',
};

// Harmony tile order (animationListSortOrder.json filtered to our effects)
const TILE_ORDER: EntranceEffect_Type[] = [
  'FADE',
  'SHUTTERS',
  'FOLD',
  'BLUR',
  'TURN',
  'EXPAND',
  'DROP',
  'TILT',
  'REVEAL',
  'SHAPE',
  'GLIDE',
  'ARC',
  'FLIP',
  'WINK',
  'SLIDE',
  'SPIN',
  'BOUNCE',
  'FLOAT',
];

// Harmony tile order (animationListSortOrder.json "ongoing", minus hidden Blink)
const LOOP_TILE_ORDER: LoopEffect_Type[] = [
  'BREATHE',
  'RUBBER',
  'FLIP',
  'POKE',
  'FOLD',
  'PULSE',
  'CROSS',
  'WIGGLE',
  'BOUNCE',
  'SPIN',
  'JELLO',
  'FLASH',
  'SWING',
];

// Harmony tile order (animationListSortOrder.json "mouse" — SpinMouse/BounceMouse are hidden)
const POINTER_TILE_ORDER: PointerEffect_Type[] = [
  'TILT_3D',
  'TRACK',
  'BLOB',
  'BLUR',
  'TRACK_3D',
  'AIRY',
  'SCALE',
  'SKEW',
  'SWIVEL',
];

// Duration/delay are stored in ms but shown in decimal seconds (Figma spec)
const TIME_STEP_SECONDS = 0.1;
const MIN_DURATION_SECONDS = 0.1;
const MAX_DURATION_SECONDS = 5;
const MIN_DELAY_SECONDS = 0;
const MAX_DELAY_SECONDS = 5;
// Loop iterations run much longer than entrances — santa classic defaults go up
// to Spin's 7s, and the schema admits 10000ms. The gap between loops reuses the
// entrance delay bounds.
const MAX_LOOP_DURATION_SECONDS = 10;
// Velocity (transitionDuration): how quickly the node settles toward the pointer
const MIN_VELOCITY_SECONDS = 0;
const MAX_VELOCITY_SECONDS = 5;
const msToSeconds = (ms: number) => ms / 1000;
const secondsToMs = (seconds: number) => Math.round(seconds * 1000);

// The panel never writes either of these, but content authored elsewhere can carry a family
// with no effect at all, or an effect a newer build introduced. Both are unrenderable here, so
// treat them as "no animation" — the same fail-open stance toMotionOptions takes for playback
// (reading `.effect.type` off the first would throw and unmount the editor's tree). The
// trade-off: such an effect shows as None, so picking a tile overwrites it.
const readSelection = (attrs: { animation?: Animation | null } | undefined) => {
  const animation = attrs?.animation ?? null;
  const viewAnimation = animation?.type === 'VIEW' ? animation : undefined;
  return {
    animation,
    entrance:
      viewAnimation?.entrance?.effect && ENTRANCE_EFFECTS[viewAnimation.entrance.effect.type]
        ? viewAnimation.entrance
        : undefined,
    loop:
      viewAnimation?.loop?.effect && LOOP_EFFECTS[viewAnimation.loop.effect.type]
        ? viewAnimation.loop
        : undefined,
    pointer:
      animation?.type === 'POINTER' && animation.effect && POINTER_EFFECTS[animation.effect.type]
        ? animation
        : undefined,
  };
};

// entrance and loop live together inside VIEW; when the last family is cleared the whole
// animation is written as null (converters strip it → the key leaves the document), so the
// schema's accepted empty-VIEW gap never reaches stored content. Composing a VIEW also
// drops any pointer animation — POINTER is structurally exclusive with VIEW.
const composeView = (
  nextEntrance: EntranceAnimation | undefined,
  nextLoop: LoopAnimation | undefined
): Animation | null =>
  nextEntrance || nextLoop
    ? {
        type: 'VIEW',
        ...(nextEntrance ? { entrance: nextEntrance } : {}),
        ...(nextLoop ? { loop: nextLoop } : {}),
      }
    : null;

// None tile — a simple diagonal line (Harmony AnimationsList NoneThumbnailIcon)
const NoneThumbnailIcon: FC = () => (
  <svg
    width="72"
    height="72"
    viewBox="0 0 72 72"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className={classes.noneThumbnailIcon}
  >
    <line
      x1="0"
      y1="72"
      x2="72"
      y2="0"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
    />
  </svg>
);

type EffectTileProps = {
  icon: ComponentType;
  label: string;
  selected: boolean;
  dataHook: string;
  customizeTooltip: string;
  onSelect: () => void;
  onCustomize: () => void;
  onHoverPreview: () => void;
  onHoverStop: () => void;
};

// One grid tile — Harmony AnimationThumbnail: MediaOverlay + Adjust overlay on
// the selected tile, 200ms-delayed hover preview on unselected tiles
const EffectTile: FC<EffectTileProps> = ({
  icon: Icon,
  label,
  selected,
  dataHook,
  customizeTooltip,
  onSelect,
  onCustomize,
  onHoverPreview,
  onHoverStop,
}) => {
  const hoverTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const clearHoverTimer = () => {
    if (hoverTimer.current) {
      clearTimeout(hoverTimer.current);
    }
  };

  // closing the panel mid-hover (the pointer never leaves the tile) would otherwise leave the
  // delay timer to fire against an unmounted tile
  useEffect(() => clearHoverTimer, []);

  const onMouseEnter = () => {
    if (selected) {
      return;
    }
    clearHoverTimer();
    hoverTimer.current = setTimeout(onHoverPreview, HOVER_PREVIEW_DELAY);
  };

  const onMouseLeave = () => {
    if (selected) {
      return;
    }
    clearHoverTimer();
    onHoverStop();
  };

  // selecting arms the click preview and turns the tile selected, where mouse leave
  // early-returns — a still-pending hover timer would fire an unstoppable preview
  // over the click's one
  const onClick = () => {
    clearHoverTimer();
    onSelect();
  };

  return (
    <div className={classes.thumbnailWrapper}>
      <Thumbnail
        size="tiny"
        selected={selected}
        onClick={onClick}
        hideSelectedIcon
        width={72}
        height={72}
        noPadding
        dataHook={dataHook}
      >
        <div className={classes.thumbnailContent}>
          <MediaOverlay
            className={classes.thumbnailMediaOverlay}
            skin={selected ? 'dark' : 'none'}
            media={
              <div onMouseEnter={onMouseEnter} onMouseLeave={onMouseLeave}>
                <Icon />
              </div>
            }
          >
            {selected ? (
              <MediaOverlay.Content visible="always" placement="middle">
                <Tooltip content={customizeTooltip}>
                  <IconButton
                    onClick={e => {
                      e.stopPropagation();
                      onCustomize();
                    }}
                    size="medium"
                    skin="light"
                    priority="primary"
                    dataHook={ANIMATION_PANEL_BUTTONS.customizeOverlay}
                  >
                    <Adjust width={24} height={24} />
                  </IconButton>
                </Tooltip>
              </MediaOverlay.Content>
            ) : null}
          </MediaOverlay>
        </div>
      </Thumbnail>
      <Text size="tiny">{label}</Text>
    </div>
  );
};

export const AnimationPanel: FC<AnimationPanelProps> = ({ nodeId, nodeType, referenceElement }) => {
  const { t } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);
  const containerEl = usePanelContainerElement();
  const { pmNodeAttrs, patchPmNodeAttrs } = useNodeAttrs(nodeId, nodeType as PmNode['type']);
  const { play, stop } = useAnimationPreview(nodeId);
  const logBi = useBiNext({ modalId: ANIMATION_PANEL_ID, pluginId: 'animation', nodeId });
  const { animation, entrance, loop, pointer } = readSelection(
    pmNodeAttrs as { animation?: Animation | null } | undefined
  );

  const [view, setView] = useState<
    'grid' | 'customize-entrance' | 'customize-loop' | 'customize-pointer'
  >('grid');
  // Open the section the user is most likely to act on: the one holding their current selection
  // — entrance wins when both view families are set, and is the default when nothing is selected
  // (a pointer selection excludes both). The panel is remounted on every open, so this is
  // re-decided each time.
  const [openFamily, setOpenFamily] = useState<AnimationFamily | null>(() => {
    if (pointer) {
      return 'pointer';
    }
    return !entrance && loop ? 'loop' : 'entrance';
  });
  // one section at a time; clicking the open one collapses it (null = all collapsed)
  const toggleSection = (family: AnimationFamily) =>
    setOpenFamily(open => (open === family ? null : family));

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: (e: MouseEvent | TouchEvent) => {
      if (referenceElement?.contains(e.target as Node)) {
        return;
      }
      modalService?.closeModal(ANIMATION_PANEL_ID);
    },
  });

  if (!pmNodeAttrs) {
    logInvariant(new Error('Animation panel: node attrs not found'));
    return null;
  }

  // customize is only reachable with an effect selected, so these are defined wherever read
  const effectConfig = entrance && ENTRANCE_EFFECTS[entrance.effect.type];
  const loopEffectConfig = loop && LOOP_EFFECTS[loop.effect.type];
  const pointerEffectConfig = pointer && POINTER_EFFECTS[pointer.effect.type];

  // the attr write is the persisted setting; WAAPI preview is purely visual. Stopping a live
  // preview is the caller's call — clearing a family stops it, dragging a slider must not.
  const writeAnimation = (next: Animation | null, previewFamily?: PreviewFamily) => {
    patchPmNodeAttrs({ animation: next });
    if (next && previewFamily) {
      play(next, previewFamily);
    }
  };

  const patchEntrance = (patch: Partial<EntranceAnimation>, preview = true) => {
    if (!entrance) {
      return;
    }
    writeAnimation(composeView({ ...entrance, ...patch }, loop), preview ? 'entrance' : undefined);
  };

  const patchLoop = (patch: Partial<LoopAnimation>, preview = true) => {
    if (!loop) {
      return;
    }
    writeAnimation(composeView(entrance, { ...loop, ...patch }), preview ? 'loop' : undefined);
  };

  // NONE in a view section clears only that family. POINTER is structurally exclusive with
  // VIEW, so while a mouse effect is stored both view families are definitionally absent —
  // composeView would resolve to null and wipe it. Same guard as clearPointer's.
  const clearEntrance = () => {
    if (!pointer) {
      writeAnimation(composeView(undefined, loop));
    }
    stop();
  };

  const selectEntranceEffect = (type: EntranceEffect_Type) => {
    // motion style lives on the effect, so replacing it resets that automatically; duration is
    // a per-effect default too and must be dropped explicitly. Only delay (a scheduling
    // choice, not an effect trait) carries over.
    writeAnimation(composeView({ delay: entrance?.delay, effect: { type } }, loop), 'entrance');
    logBi?.({ dataHook: ANIMATION_PANEL_BUTTONS.tile('entrance', type), value: type });
  };

  const clearLoop = () => {
    if (!pointer) {
      writeAnimation(composeView(entrance, undefined));
    }
    stop();
  };

  const selectLoopEffect = (type: LoopEffect_Type) => {
    // duration and the delay between loops are both per-effect defaults (santa classic gives
    // every effect its own gap), so nothing carries over on effect change
    writeAnimation(composeView(entrance, { effect: { type } }), 'loop');
    logBi?.({ dataHook: ANIMATION_PANEL_BUTTONS.tile('loop', type), value: type });
  };

  // NONE in the mouse section clears only a pointer animation — an entrance/loop
  // selection lives in the other variant and must survive it
  const clearPointer = () => {
    if (pointer) {
      writeAnimation(null);
    }
    stop();
  };

  const patchPointer = (patch: Partial<Omit<Animation_Pointer, 'type'>>, preview = true) => {
    if (!pointer) {
      return;
    }
    writeAnimation({ ...pointer, ...patch }, preview ? 'pointer' : undefined);
  };

  // picking a mouse effect replaces the whole animation — POINTER is structurally
  // exclusive with VIEW (and vice versa: picking an entrance/loop tile composes a
  // fresh VIEW, dropping the pointer)
  const selectPointerEffect = (type: PointerEffect_Type) => {
    writeAnimation({ type: 'POINTER', effect: { type } }, 'pointer');
    logBi?.({ dataHook: ANIMATION_PANEL_BUTTONS.tile('pointer', type), value: type });
  };

  // transient hover preview — plays the hovered effect on the node with
  // default params, never touching the stored animation
  const onEntranceHoverPreview = (type: EntranceEffect_Type) =>
    play({ type: 'VIEW', entrance: { effect: { type } } }, 'entrance');
  const onLoopHoverPreview = (type: LoopEffect_Type) =>
    play({ type: 'VIEW', loop: { effect: { type } } }, 'loop');
  const onPointerHoverPreview = (type: PointerEffect_Type) =>
    play({ type: 'POINTER', effect: { type } }, 'pointer');

  const previewChip = (family: PreviewFamily, label: string) => (
    <Badge
      uppercase={false}
      skin="standard"
      size="small"
      type="outlined"
      dataHook={ANIMATION_PANEL_BUTTONS.replay}
      onClick={(e: React.SyntheticEvent) => {
        e.stopPropagation();
        if (animation) {
          play(animation, family);
        }
      }}
    >
      {/* 16px, not 18: the small Badge is 18px tall with a 1px border, so a
          same-size glyph overflows its content box and stretches the chip */}
      <Box verticalAlign="middle" gap="4px">
        <Play height={16} width={16} />
        {label}
      </Box>
    </Badge>
  );

  const noneTile = (family: AnimationFamily, selected: boolean, onSelect: () => void) => (
    <div className={classes.thumbnailWrapper}>
      <Thumbnail
        size="tiny"
        selected={selected}
        onClick={onSelect}
        hideSelectedIcon
        width={72}
        height={72}
        noPadding
        dataHook={ANIMATION_PANEL_BUTTONS.tile(family, NONE)}
      >
        <div className={classes.thumbnailContent}>
          <NoneThumbnailIcon />
        </div>
      </Thumbnail>
      <Text size="tiny">{t('AnimationPanel_Effect_None')}</Text>
    </div>
  );

  const entranceTileGrid = (
    <div className={classes.thumbnailsGrid}>
      {noneTile('entrance', !entrance, clearEntrance)}
      {TILE_ORDER.map(type => (
        <EffectTile
          key={type}
          icon={EFFECT_TILE_ICONS[type]}
          label={t(EFFECT_LABEL_KEYS[type])}
          selected={type === entrance?.effect.type}
          dataHook={ANIMATION_PANEL_BUTTONS.tile('entrance', type)}
          customizeTooltip={t('AnimationPanel_Customize_Tooltip')}
          onSelect={() => selectEntranceEffect(type)}
          onCustomize={() => setView('customize-entrance')}
          onHoverPreview={() => onEntranceHoverPreview(type)}
          onHoverStop={stop}
        />
      ))}
    </div>
  );

  const loopTileGrid = (
    <div className={classes.thumbnailsGrid}>
      {noneTile('loop', !loop, clearLoop)}
      {LOOP_TILE_ORDER.map(type => (
        <EffectTile
          key={type}
          icon={LOOP_EFFECT_TILE_ICONS[type]}
          label={t(LOOP_EFFECT_LABEL_KEYS[type])}
          selected={type === loop?.effect.type}
          dataHook={ANIMATION_PANEL_BUTTONS.tile('loop', type)}
          customizeTooltip={t('AnimationPanel_Customize_Tooltip')}
          onSelect={() => selectLoopEffect(type)}
          onCustomize={() => setView('customize-loop')}
          onHoverPreview={() => onLoopHoverPreview(type)}
          onHoverStop={stop}
        />
      ))}
    </div>
  );

  const pointerTileGrid = (
    <div className={classes.thumbnailsGrid}>
      {noneTile('pointer', !pointer, clearPointer)}
      {POINTER_TILE_ORDER.map(type => (
        <EffectTile
          key={type}
          icon={POINTER_EFFECT_TILE_ICONS[type]}
          label={t(POINTER_EFFECT_LABEL_KEYS[type])}
          selected={type === pointer?.effect.type}
          dataHook={ANIMATION_PANEL_BUTTONS.tile('pointer', type)}
          customizeTooltip={t('AnimationPanel_Customize_Tooltip')}
          onSelect={() => selectPointerEffect(type)}
          onCustomize={() => setView('customize-pointer')}
          onHoverPreview={() => onPointerHoverPreview(type)}
          onHoverStop={stop}
        />
      ))}
    </div>
  );

  const sectionItem = (family: AnimationFamily, title: string, chip: ReactNode, grid: ReactNode) =>
    accordionItemBuilder({
      title,
      buttonType: 'node',
      showLabel: 'always',
      expandLabel: (
        <span className={classes.sectionSlot}>
          <ChevronDown />
        </span>
      ),
      collapseLabel: (
        <span className={classes.sectionSlot}>
          <ChevronUp />
        </span>
      ),
      suffix: chip && <span className={classes.sectionSlot}>{chip}</span>,
      open: openFamily === family,
      onToggle: () => toggleSection(family),
      children: grid,
    });

  const sectionItems = [
    sectionItem(
      'entrance',
      t('AnimationPanel_Section_Entrance'),
      entrance ? previewChip('entrance', t(EFFECT_LABEL_KEYS[entrance.effect.type])) : null,
      entranceTileGrid
    ),
    sectionItem(
      'loop',
      t('AnimationPanel_Section_Loop'),
      loop ? previewChip('loop', t(LOOP_EFFECT_LABEL_KEYS[loop.effect.type])) : null,
      loopTileGrid
    ),
    sectionItem(
      'pointer',
      t('AnimationPanel_Section_Mouse'),
      pointer ? previewChip('pointer', t(POINTER_EFFECT_LABEL_KEYS[pointer.effect.type])) : null,
      pointerTileGrid
    ),
  ];

  // customize is only reachable with a selected effect in that family; fall back to
  // the grid if the family is cleared while its customize view is open
  const activeView =
    (view === 'customize-entrance' && entrance) ||
    (view === 'customize-loop' && loop) ||
    (view === 'customize-pointer' && pointer)
      ? view
      : 'grid';

  // `entrance`/`loop`/`pointer` are re-tested only to narrow them — activeView already implies each
  const headerTitle =
    activeView === 'customize-entrance' && entrance
      ? t(EFFECT_LABEL_KEYS[entrance.effect.type])
      : activeView === 'customize-loop' && loop
        ? t(LOOP_EFFECT_LABEL_KEYS[loop.effect.type])
        : activeView === 'customize-pointer' && pointer
          ? t(POINTER_EFFECT_LABEL_KEYS[pointer.effect.type])
          : t('AnimationPanel_Header');

  const previewRow = (family: PreviewFamily) => (
    <div className={classes.previewRow}>
      <Text size="small">{t('AnimationPanel_Preview_Label')}</Text>
      <IconButton
        size="medium"
        skin="standard"
        priority="secondary"
        onClick={() => animation && play(animation, family)}
        dataHook={ANIMATION_PANEL_BUTTONS.preview}
        aria-label={t('AnimationPanel_Preview_AriaLabel')}
      >
        <Play />
      </IconButton>
    </div>
  );

  return (
    <Panel
      closeButtonProps={{ onClick: () => modalService?.closeModal(ANIMATION_PANEL_ID) }}
      backButtonProps={
        activeView !== 'grid'
          ? { onClick: () => setView('grid'), ariaLabel: t('AnimationPanel_Back_AriaLabel') }
          : undefined
      }
      dataHook={ANIMATION_PANEL}
    >
      <PanelHeader title={headerTitle} />

      {activeView === 'grid' && (
        <div
          className={classes.sections}
          // every section header stays visible, so the tile list's height budget is the panel's
          // minus one header per section — publishing the count keeps that in the stylesheet
          style={{ '--ricos-internal-animation-sections': sectionItems.length } as CSSProperties}
        >
          <Accordion
            skin="light"
            hideShadow
            size="tiny"
            contentPadding="none"
            titleSize="small"
            dataHook={ANIMATION_PANEL_BUTTONS.sections}
            items={sectionItems}
          />
        </div>
      )}

      {activeView === 'customize-entrance' && entrance && effectConfig && (
        <>
          {previewRow('entrance')}
          <Divider />
          <Box direction="vertical" gap="18px" padding="18px">
            <EffectControls
              effect={entrance.effect}
              onChange={effect => patchEntrance({ effect })}
              logBi={logBi}
            />
            <SliderWithInput
              label={t('AnimationPanel_Duration_Label')}
              min={MIN_DURATION_SECONDS}
              max={MAX_DURATION_SECONDS}
              step={TIME_STEP_SECONDS}
              // omit-until-touched: the slider shows the effect's default, but the
              // document only stores duration once the user changes it
              value={msToSeconds(entrance.duration ?? effectConfig.duration)}
              onChange={seconds => patchEntrance({ duration: secondsToMs(seconds) }, false)}
              sliderDataHook={ANIMATION_PANEL_BUTTONS.durationSlider('entrance')}
              inputDataHook={ANIMATION_PANEL_BUTTONS.durationInput('entrance')}
              logBi={logBi}
            />
            <SliderWithInput
              label={t('AnimationPanel_Delay_Label')}
              min={MIN_DELAY_SECONDS}
              max={MAX_DELAY_SECONDS}
              step={TIME_STEP_SECONDS}
              value={msToSeconds(entrance.delay ?? 0)}
              onChange={seconds => patchEntrance({ delay: secondsToMs(seconds) }, false)}
              sliderDataHook={ANIMATION_PANEL_BUTTONS.delaySlider('entrance')}
              inputDataHook={ANIMATION_PANEL_BUTTONS.delayInput('entrance')}
              logBi={logBi}
            />
          </Box>
        </>
      )}

      {activeView === 'customize-loop' && loop && loopEffectConfig && (
        <>
          {previewRow('loop')}
          <Divider />
          <Box direction="vertical" gap="18px" padding="18px">
            <LoopEffectControls
              effect={loop.effect}
              onChange={effect => patchLoop({ effect })}
              logBi={logBi}
            />
            <SliderWithInput
              label={t('AnimationPanel_Duration_Label')}
              min={MIN_DURATION_SECONDS}
              max={MAX_LOOP_DURATION_SECONDS}
              step={TIME_STEP_SECONDS}
              value={msToSeconds(loop.duration ?? loopEffectConfig.duration)}
              onChange={seconds => patchLoop({ duration: secondsToMs(seconds) }, false)}
              sliderDataHook={ANIMATION_PANEL_BUTTONS.durationSlider('loop')}
              inputDataHook={ANIMATION_PANEL_BUTTONS.durationInput('loop')}
              logBi={logBi}
            />
            <SliderWithInput
              label={t('AnimationPanel_LoopDelay_Label')}
              min={MIN_DELAY_SECONDS}
              max={MAX_DELAY_SECONDS}
              step={TIME_STEP_SECONDS}
              value={msToSeconds(loop.iterationDelay ?? loopEffectConfig.iterationDelay)}
              onChange={seconds => patchLoop({ iterationDelay: secondsToMs(seconds) }, false)}
              sliderDataHook={ANIMATION_PANEL_BUTTONS.delaySlider('loop')}
              inputDataHook={ANIMATION_PANEL_BUTTONS.delayInput('loop')}
              logBi={logBi}
            />
          </Box>
        </>
      )}

      {activeView === 'customize-pointer' && pointer && pointerEffectConfig && (
        <>
          {previewRow('pointer')}
          <Divider />
          <Box direction="vertical" gap="18px" padding="18px">
            <PointerEffectControls
              effect={pointer.effect}
              onChange={effect => patchPointer({ effect })}
              logBi={logBi}
            />
            <SliderWithInput
              label={t('AnimationPanel_Velocity_Label')}
              min={MIN_VELOCITY_SECONDS}
              max={MAX_VELOCITY_SECONDS}
              step={TIME_STEP_SECONDS}
              value={msToSeconds(
                pointer.transitionDuration ?? pointerEffectConfig.transitionDuration
              )}
              onChange={seconds =>
                patchPointer({ transitionDuration: secondsToMs(seconds) }, false)
              }
              sliderDataHook={ANIMATION_PANEL_BUTTONS.durationSlider('pointer')}
              inputDataHook={ANIMATION_PANEL_BUTTONS.durationInput('pointer')}
              logBi={logBi}
            />
            <PointerEffectEndControls
              effect={pointer.effect}
              onChange={effect => patchPointer({ effect })}
              logBi={logBi}
            />
          </Box>
        </>
      )}
    </Panel>
  );
};
