import {
  ArrowDown,
  ArrowLeftRight,
  ArrowUpDown,
  Move,
  Revert,
  RevertClockwise,
} from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

// Icon shows the direction of travel (opposite of the "from" origin), e.g. an
// entrance animation that comes "from top" travels downward → ArrowDown.
// WDS has no diagonal-arrow assets, so — like Harmony's motion-effects-panels —
// a single ArrowDown is rotated instead of shipping eight separate glyphs.
const ARROW_ROTATION: Record<string, number> = {
  TOP: 0,
  TOP_RIGHT: 45,
  RIGHT: 90,
  BOTTOM_RIGHT: 135,
  BOTTOM: 180,
  BOTTOM_LEFT: 225,
  LEFT: 270,
  TOP_LEFT: 315,
};

const RotatedArrow: React.FC<{ degrees: number }> = ({ degrees }) => (
  <span style={{ display: 'flex', rotate: `${degrees}deg` }}>
    <ArrowDown />
  </span>
);

// "From center" — concentric ring + dot, mirroring the Vignette glyph Harmony
// uses. Vignette only ships in the /odeditor entry, and one-ricos imports icons
// from the package root, so it's inlined rather than pulling in a second entry.
const CenterIcon: React.FC = () => (
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <circle cx="12" cy="12" r="7.5" stroke="currentColor" />
    <circle cx="12" cy="12" r="2.5" fill="currentColor" />
  </svg>
);

const horizontal = <ArrowLeftRight />;
const vertical = <ArrowUpDown />;

export const DIRECTION_ICONS: Partial<Record<string, React.ReactNode>> = {
  ...Object.fromEntries(
    Object.entries(ARROW_ROTATION).map(([direction, degrees]) => [
      direction,
      <RotatedArrow key={direction} degrees={degrees} />,
    ])
  ),
  CENTER: <CenterIcon />,
  HORIZONTAL: horizontal,
  VERTICAL: vertical,
  // SWIVEL's pivot enum spells the same two axes CENTER_* — its hinge is that centre line
  CENTER_HORIZONTAL: horizontal,
  CENTER_VERTICAL: vertical,
  // both axes at once — Move's four-way arrows next to the single-axis pair above
  BOTH: <Move />,
  CLOCKWISE: <RevertClockwise />,
  COUNTER_CLOCKWISE: <Revert />,
};
