import { ANIMATION_TYPE } from './../ricos-content/index.js';
import type { EditorPluginCreator } from './../ricos-types/index.js';

import { AnimationPanel } from './animation-panel.js';
import { getTextButtons } from './get-text-buttons.js';

export interface AnimationPluginEditorConfig {
  type: 'animation';
}

/** Internal creator resolved via pluginsMap — the public factory lives in options.ts. */
export const pluginAnimation: EditorPluginCreator<AnimationPluginEditorConfig> = config => ({
  config: { type: 'animation' as const, ...config },
  type: ANIMATION_TYPE,
  tiptapExtensions: [],
  textButtons: getTextButtons(),
  exports: { animation: { Panel: AnimationPanel } },
});
