export const ANIMATION_PANEL = 'animation-panel-modal';

export const TEXT_BUTTON_ANIMATION = 'text-button-animation';

export type AnimationFamily = 'entrance' | 'loop' | 'pointer';

export const ANIMATION_PANEL_BUTTONS = {
  // family-qualified: BOUNCE/FLIP/FOLD/SPIN exist in both the entrance and loop
  // unions, BLUR in entrance and pointer
  tile: (family: AnimationFamily, effect: string) =>
    `animation-panel-tile-${family}-${effect.toLowerCase()}`,
  customizeOverlay: 'animation-panel-customize-overlay',
  // the one Accordion holding every family's section — WDS accordion items take no dataHook
  sections: 'animation-panel-sections',
  paramInvert: 'animation-panel-param-invert',
  // `param` and `paramThumbnails` stay unqualified — no effect renders two of either
  param: 'animation-panel-param-select',
  // key-qualified like `tile`: SCALE renders two segmented toggles (movement axis and scale
  // direction), and BI logs the dataHook as the event's identity. `-${key}-toggle` rather than
  // `-toggle-${key}` so it can never collide with a `paramToggleOption` string.
  paramToggle: (key: string) => `animation-panel-param-${key}-toggle`,
  paramToggleOption: (option: string) => `animation-panel-param-toggle-${option.toLowerCase()}`,
  paramThumbnails: 'animation-panel-param-thumbnails',
  paramThumbnail: (option: string) => `animation-panel-param-thumbnail-${option.toLowerCase()}`,
  // family-qualified like `tile`: both customize views have a duration and a delay slider,
  // and BI logs the dataHook as the event's identity
  durationSlider: (family: AnimationFamily) => `animation-panel-${family}-duration-slider`,
  durationInput: (family: AnimationFamily) => `animation-panel-${family}-duration-input`,
  delaySlider: (family: AnimationFamily) => `animation-panel-${family}-delay-slider`,
  delayInput: (family: AnimationFamily) => `animation-panel-${family}-delay-input`,
  motionStyle: 'animation-panel-motion-style',
  replay: 'animation-panel-replay-button',
  preview: 'animation-panel-preview-button',
};
