import type { Resolver } from './../ricos-types/index.js';
import { PmNodeType } from './../_shared/pm-node-types.js';
import type { Editor } from './../tiptap/core/index.js';
import type { Node as ProseMirrorNode } from './../tiptap/pm/model.js';
import type { NodeSelection } from './../tiptap/pm/state.js';
import type { AnimatablePmType } from './../tiptap-extensions/node-animation.js';

// The text blocks whose data payload carries `animation` and which have no
// plugin toolbar of their own (subset of ANIMATABLE_PM_TYPES in
// tiptap-extensions/node-animation.ts; every other animatable node gets the
// shared animation button from its plugin toolbar). Typed against the same
// schema-derived union, so an entry that stops being animatable fails the build.
const ANIMATABLE_TEXT_BLOCK_TYPES: ReadonlySet<string> = new Set<AnimatablePmType>([
  PmNodeType.PARAGRAPH,
  PmNodeType.HEADING,
  PmNodeType.BULLETED_LIST,
  PmNodeType.ORDERED_LIST,
  PmNodeType.CHECKBOX_LIST,
  PmNodeType.BLOCKQUOTE,
  PmNodeType.CODE_BLOCK,
]);

/**
 * Resolves the single text block containing the selection, at any depth:
 * - NodeSelection on an animatable text block → that block
 * - cursor/TextSelection inside one block → the outermost animatable text block
 *   fully containing the selection (cursor in a list resolves the whole list —
 *   one list = one block; nested containers like table cells, collapsible
 *   bodies, layout cells and cards no longer block resolution below them)
 * - selection spanning two+ blocks with no common animatable ancestor → undefined
 */
export const findAnimatableTextBlockInSelection = (
  editor: Editor | undefined | null
): ProseMirrorNode | undefined => {
  const state = editor?.state;
  if (!state || state.doc.childCount === 0) {
    return undefined;
  }
  const selectedNode = (state.selection as NodeSelection).node as ProseMirrorNode | undefined;
  if (selectedNode) {
    return ANIMATABLE_TEXT_BLOCK_TYPES.has(selectedNode.type.name) ? selectedNode : undefined;
  }
  const { $from, $to, empty } = state.selection;
  const sharedDepth = empty ? $from.depth : $from.sharedDepth($to.pos);
  // outermost animatable ancestor containing the whole selection
  for (let depth = 1; depth <= sharedDepth; depth++) {
    const node = $from.node(depth);
    if (ANIMATABLE_TEXT_BLOCK_TYPES.has(node.type.name)) {
      return node;
    }
  }
  // no animatable ancestor — the selection may still sit inside a single child
  // of the shared ancestor (e.g. select-all over a one-block document)
  const fromIndex = $from.index(sharedDepth);
  const toIndex = empty ? fromIndex : $to.indexAfter(sharedDepth) - 1;
  if (fromIndex !== toIndex) {
    return undefined;
  }
  const child = $from.node(sharedDepth).maybeChild(fromIndex);
  return child && ANIMATABLE_TEXT_BLOCK_TYPES.has(child.type.name) ? child : undefined;
};

export const getAnimatableTextBlockInSelection: Resolver<ProseMirrorNode | undefined> = (
  _content,
  _services,
  editor
) => findAnimatableTextBlockInSelection(editor);
