import type {
  Animation_Easing,
  EntranceEffect,
  EntranceEffect_Type,
} from './../../ricos-schema/next-schema/index.js';

/** The optional params a given effect owns, with its discriminant removed. */
export type EntranceEffectParams<T extends EntranceEffect_Type> = Omit<
  Extract<EntranceEffect, { type: T }>,
  'type'
>;

export type EntranceEffectConfig<T extends EntranceEffect_Type = EntranceEffect_Type> = {
  /** `@wix/motion-presets` preset this effect plays — must match a key registered in `motion-runtime`. */
  preset: string;
  /** Default duration in ms. Motion has no tuned default — a missing duration is coerced to 1ms. */
  duration: number;
  /**
   * Defaults for the effect's own params — including `easing` (motion style) for the effects that
   * expose one. Typed from the schema variant, so an effect that declares no `easing` can't be
   * given a motion-style default here.
   */
  params?: EntranceEffectParams<T>;
};

/**
 * The single source of truth for every ricos-owned entrance-effect default.
 *
 * Mirrors santa-editor's `@wix/effects-kit` classic-editor config, so an animation configured in
 * ricos looks identical to the same one configured in the Wix editor. Motion's presets carry their
 * own defaults, but they routinely disagree with the panel tile the user picks by — and the tile is
 * the source of truth.
 *
 * Defaults are injected at playback time rather than written into the document: stored documents
 * stay omit-until-touched, so re-tuning applies retroactively and upstream preset re-tuning can't
 * change how existing documents look.
 *
 * Direction values name the *origin* of the motion ("enters from"), matching the panel's vocabulary.
 */
export const ENTRANCE_EFFECTS: { [T in EntranceEffect_Type]: EntranceEffectConfig<T> } = {
  FADE: { preset: 'FadeIn', duration: 1200 },
  ARC: { preset: 'ArcIn', duration: 1200, params: { direction: 'LEFT', easing: 'MODERATE' } },
  BLUR: { preset: 'BlurIn', duration: 2000, params: { easing: 'GENTLE' } },
  BOUNCE: { preset: 'BounceIn', duration: 1200, params: { direction: 'TOP', easing: 'GENTLE' } },
  DROP: { preset: 'DropIn', duration: 1200, params: { easing: 'GENTLE' } },
  EXPAND: { preset: 'ExpandIn', duration: 1200, params: { direction: 'CENTER', easing: 'GENTLE' } },
  FLIP: { preset: 'FlipIn', duration: 1200, params: { direction: 'BOTTOM', easing: 'GENTLE' } },
  FLOAT: { preset: 'FloatIn', duration: 1200, params: { direction: 'BOTTOM' } },
  FOLD: { preset: 'FoldIn', duration: 1200, params: { direction: 'TOP', easing: 'INTENSE' } },
  GLIDE: { preset: 'GlideIn', duration: 1200, params: { direction: 'BOTTOM', easing: 'GENTLE' } },
  REVEAL: { preset: 'RevealIn', duration: 1200, params: { direction: 'BOTTOM' } },
  SHAPE: { preset: 'ShapeIn', duration: 1500, params: { shape: 'CIRCLE' } },
  SHUTTERS: { preset: 'ShuttersIn', duration: 1200, params: { direction: 'RIGHT' } },
  SLIDE: { preset: 'SlideIn', duration: 1200, params: { direction: 'BOTTOM', easing: 'INTENSE' } },
  SPIN: {
    preset: 'SpinIn',
    duration: 1800,
    params: { direction: 'CLOCKWISE', easing: 'MODERATE' },
  },
  TILT: { preset: 'TiltIn', duration: 1200, params: { direction: 'LEFT' } },
  TURN: {
    preset: 'TurnIn',
    duration: 1000,
    params: { direction: 'BOTTOM_LEFT', easing: 'INTENSE' },
  },
  WINK: { preset: 'WinkIn', duration: 1200, params: { direction: 'VERTICAL' } },
};

/**
 * The effect's default motion style, or `undefined` when it has none. Reading `.easing` off the
 * params union isn't type-safe (only 11 of the 18 variants declare it), so go through here.
 */
export const defaultEasingOf = (type: EntranceEffect_Type): Animation_Easing | undefined =>
  (ENTRANCE_EFFECTS[type].params as { easing?: Animation_Easing } | undefined)?.easing;
