import { FieldSet, RadioGroup, type RadioGroupProps } from '@wix/design-system';
import React from 'react';

import type { LogBiFn } from './../../_shared/bi-context-provider/bi-context-provider.js';

type RadioGroupWithLabelProps<T extends string> = {
  label: string;
  dataHook: string;
  value: T;
  onChange: (value: T) => void;
  options: {
    id: T;
    value: string;
  }[];
  logBi?: LogBiFn;
};

export const RadioGroupWithLabel = <T extends string>({
  label,
  dataHook,
  value,
  onChange,
  options,
  logBi,
}: RadioGroupWithLabelProps<T>) => {
  const handleChange = (nextValue: RadioGroupProps['value']) => {
    logBi?.({ dataHook, value: nextValue });
    onChange(nextValue as T);
  };

  return (
    <FieldSet legend={label} legendSize="small" legendPlacement="top">
      <RadioGroup dataHook={dataHook} value={value} onChange={handleChange} size="small">
        {options.map(option => (
          <RadioGroup.Radio
            key={option.id}
            value={option.id}
            dataHook={`${dataHook}-${option.id.toLowerCase()}`}
          >
            {option.value}
          </RadioGroup.Radio>
        ))}
      </RadioGroup>
    </FieldSet>
  );
};
