import { FormField, SegmentedToggle } from '@wix/design-system';
import React, { useContext } from 'react';

import { RicosContext } from './../ricos-context/index.js';
import type { PointerEffect } from './../ricos-schema/next-schema/index.js';
import {
  Animation_Axis,
  PointerEffect_Scale_Direction,
  PointerEffect_Swivel_Axis,
} from './../ricos-schema/next-schema/index.js';
import type { LogBiFn } from './../_shared/bi-context-provider/bi-context-provider.js';
import { defaultPointerEasingOf, POINTER_EFFECTS } from './../_shared/node-animation/pointer-effects.js';

import { ANIMATION_PANEL_BUTTONS } from './data-hooks.js';
import type { ParamControl, SlottedParamControls } from './effect-controls.js';
import { MotionStyleField, ParamControlField } from './effect-controls.js';

const axisToggle: ParamControl<'axis'> = {
  kind: 'segmented',
  key: 'axis',
  labelKey: 'AnimationPanel_Axis_Label',
  options: Object.values(Animation_Axis),
  // HORIZONTAL/VERTICAL reuse the shared vocabulary; BOTH is axis-specific
  optionLabelKeys: { BOTH: 'AnimationPanel_Axis_Both' },
};

const scaleDirectionToggle: ParamControl<'direction'> = {
  kind: 'segmented',
  // "Expand"/"Shrink" have no arrow to draw — words, not glyphs
  labels: 'text',
  key: 'direction',
  labelKey: 'AnimationPanel_ScaleDirection_Label',
  options: Object.values(PointerEffect_Scale_Direction),
  optionLabelKeys: {
    UP: 'AnimationPanel_ScaleDirection_Up',
    DOWN: 'AnimationPanel_ScaleDirection_Down',
  },
};

const pivotSelect: ParamControl<'axis'> = {
  kind: 'select',
  key: 'axis',
  labelKey: 'AnimationPanel_PivotAxis_Label',
  options: Object.values(PointerEffect_Swivel_Axis),
};

/**
 * The params each mouse effect exposes and the slot each sits in — the pointer twin of
 * `EFFECT_PARAM_CONTROL`, same rule for the values: options derive from the schema's own
 * enums. TILT_3D/BLOB/BLUR expose none.
 *
 * SWIVEL spells its pivot with the same `axis` key as the movement-axis effects, over its
 * own disjoint enum — hence a second, differently-labelled `axis` control above.
 */
export const POINTER_EFFECT_PARAM_CONTROL: SlottedParamControls<PointerEffect> = {
  AIRY: { top: axisToggle },
  SKEW: { top: axisToggle },
  TRACK: { top: axisToggle },
  TRACK_3D: { top: axisToggle },
  // the only effect with two: the shared movement axis, plus its own expand/shrink
  SCALE: { top: axisToggle, middle: scaleDirectionToggle },
  // the pivot is SWIVEL's identity rather than a constraint on its movement — it reads last
  SWIVEL: { end: pivotSelect },
};

type Props = {
  effect: PointerEffect;
  onChange: (effect: PointerEffect) => void;
  logBi: LogBiFn;
};

/**
 * The schema keeps `inverted` a boolean; the toggle spells it as the two behaviours it
 * names, so the panel reads as a choice rather than as an unexplained switch.
 */
const FOLLOW = 'FOLLOW';
const INVERT = 'INVERT';

export const MOUSE_MOVEMENT_OPTIONS = [
  { value: FOLLOW, labelKey: 'AnimationPanel_MouseMovement_Follow' },
  { value: INVERT, labelKey: 'AnimationPanel_Invert_Label' },
];

/** Every mouse effect stores `inverted` — react away from the pointer instead of toward it. */
const InvertControl: React.FC<Props> = ({ effect, onChange, logBi }) => {
  const { t } = useContext(RicosContext);
  const defaults = POINTER_EFFECTS[effect.type].params as { inverted?: boolean } | undefined;
  const inverted = (effect as { inverted?: boolean }).inverted ?? defaults?.inverted ?? false;

  return (
    <FormField label={t('AnimationPanel_MouseMovement_Label')}>
      <SegmentedToggle
        selected={inverted ? INVERT : FOLLOW}
        // WDS fires onClick on the already-selected segment too — see the param toggle
        onClick={(_, value: string) => {
          const next = value === INVERT;
          if (next === inverted) {
            return;
          }
          logBi?.({ dataHook: ANIMATION_PANEL_BUTTONS.paramInvert, value: String(next) });
          onChange({ ...effect, inverted: next });
        }}
        size="small"
        fullWidth
        dataHook={ANIMATION_PANEL_BUTTONS.paramInvert}
      >
        {MOUSE_MOVEMENT_OPTIONS.map(option => (
          <SegmentedToggle.Button
            key={option.value}
            value={option.value}
            dataHook={ANIMATION_PANEL_BUTTONS.paramToggleOption(option.value)}
          >
            {t(option.labelKey)}
          </SegmentedToggle.Button>
        ))}
      </SegmentedToggle>
    </FormField>
  );
};

const defaultsOf = (effect: PointerEffect) =>
  POINTER_EFFECTS[effect.type].params as Record<string, unknown> | undefined;

/**
 * Every control that reads above the Velocity slider, in the classic panel's order: invert,
 * the movement axis, motion style, then the effect's remaining param. Velocity is the
 * envelope's (`transitionDuration`) and stays with the panel — which is why the one control
 * that reads below it is a second component rather than more children here.
 */
export const PointerEffectControls: React.FC<Props> = ({ effect, onChange, logBi }) => {
  const slots = POINTER_EFFECT_PARAM_CONTROL[effect.type];

  return (
    <>
      <InvertControl effect={effect} onChange={onChange} logBi={logBi} />
      <ParamControlField
        effect={effect}
        onChange={onChange}
        logBi={logBi}
        control={slots?.top}
        defaults={defaultsOf(effect)}
      />
      <MotionStyleField
        effect={effect}
        onChange={onChange}
        logBi={logBi}
        defaultEasing={defaultPointerEasingOf(effect.type)}
      />
      <ParamControlField
        effect={effect}
        onChange={onChange}
        logBi={logBi}
        control={slots?.middle}
        defaults={defaultsOf(effect)}
      />
    </>
  );
};

/** The one param that reads below Velocity — SWIVEL's pivot axis. */
export const PointerEffectEndControls: React.FC<Props> = ({ effect, onChange, logBi }) => (
  <ParamControlField
    effect={effect}
    onChange={onChange}
    logBi={logBi}
    control={POINTER_EFFECT_PARAM_CONTROL[effect.type]?.end}
    defaults={defaultsOf(effect)}
  />
);
