import { Animation } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../ricos-modals/modal-service-provider.js';
import type { IToolbarItem, TextButton } from './../ricos-types/index.js';
import { ANIMATION_PANEL_ID } from './../_shared/plugin-toolbar/create-animation-button.js';
import { isAlwaysVisible } from './../_shared/resolvers/is-always-visible.js';
import { ToolbarButton } from './../_shared/toolbar-button/toolbar-button.js';
import { FORMATTING_BUTTONS } from './../editor-common/index.js';

import { AnimationPanel } from './animation-panel.js';
import { TEXT_BUTTON_ANIMATION } from './data-hooks.js';
import {
  findAnimatableTextBlockInSelection,
  getAnimatableTextBlockInSelection,
} from './get-animatable-text-block-in-selection.js';

/**
 * Formatting-toolbar counterpart of the shared plugin-toolbar animation button
 * (#shared/plugin-toolbar/create-animation-button.tsx). Text blocks never
 * produce a NodeSelection, so this button resolves its target from the text
 * selection instead: the single text block containing it, at any depth.
 */
export const getTextButtons = (): TextButton[] => [
  {
    id: FORMATTING_BUTTONS.ANIMATION,
    type: 'modal',
    presentation: {
      dataHook: TEXT_BUTTON_ANIMATION,
      tooltip: 'AnimationButton_Tooltip',
      icon: Animation,
      renderer: toolbarItem => <AnimationTextButton toolbarItem={toolbarItem} />,
    },
    attributes: {
      visible: isAlwaysVisible,
      // formatting toolbars render with type='floating', which filters OUT
      // disabled buttons; alwaysVisible keeps the button mounted so it shows
      // as disabled instead of disappearing on multi-block selections
      alwaysVisible: isAlwaysVisible,
      disabled: (content, services, editor) =>
        !getAnimatableTextBlockInSelection(content, services, editor),
      // the LINK button's contract: active whenever the target block already carries
      // an animation, panel-open state is ORed in by the renderer
      active: (content, services, editor) =>
        Boolean(getAnimatableTextBlockInSelection(content, services, editor)?.attrs.animation),
    },
    command:
      ({ modalService, referenceElement, editor }) =>
      () => {
        // non-exclusive open/close (headings & text-color precedent):
        // togglePluginPanel is type 'exclusive', which unmounts the floating
        // formatting toolbar and detaches the panel's positioning anchor
        if (modalService.isModalOpen(ANIMATION_PANEL_ID)) {
          modalService.closeModal(ANIMATION_PANEL_ID);
          return true;
        }
        const block = findAnimatableTextBlockInSelection(editor);
        if (!block?.attrs.id) {
          return false;
        }
        modalService.openModal({
          id: ANIMATION_PANEL_ID,
          Component: AnimationPanel,
          componentProps: {
            referenceElement,
            nodeId: block.attrs.id,
            nodeType: block.type.name,
          },
          layout: {
            desktop: referenceElement ? 'floating' : 'dialog',
            mobile: 'drawer',
          },
          ...(referenceElement && {
            positioning: { placement: 'bottom', referenceElement },
          }),
          // AnimationPanel closes itself via its own useClickOutside, which
          // ignores clicks on referenceElement — that makes button-click toggle
          onClickOutside: {
            on: 'pointerup',
            handler: () => {},
          },
          returnFocusToEditor: true,
          disableArrowNavigation: true,
          enableDrag: true,
          dragHandleSelector: '[data-drag-handler]',
          withTransition: true,
        });
        return true;
      },
  },
];

const AnimationTextButton: FC<{ toolbarItem: IToolbarItem; dataHook?: string }> = ({
  toolbarItem,
  dataHook,
}) => {
  const { t } = useContext(RicosContext);
  const isPanelOpen = useModalState(getIsModalOpen(ANIMATION_PANEL_ID));
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);

  return (
    <ToolbarButton
      ref={setReferenceElement}
      active={isPanelOpen || Boolean(toolbarItem.attributes.active)}
      disabled={Boolean(toolbarItem.attributes.disabled)}
      prefix={Animation}
      tooltip={t(toolbarItem.presentation?.tooltip ?? 'AnimationButton_Tooltip')}
      onClick={() => toolbarItem.commands.click({ referenceElement })}
      dataHook={dataHook ?? TEXT_BUTTON_ANIMATION}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
