import { useContext, useEffect, useMemo, useRef } from 'react';

import { EditorContext } from './../ricos-context/index.js';
import type { Animation } from './../ricos-schema/next-schema/index.js';
import { setAnimationPreviewing } from './../_shared/node-animation/animation-preview-signal.js';
// static, unlike the motion runtime below: this module and its `pointer-effects` dependency
// import `@wix/motion` type-only, so it costs nothing until the panel opens
import { toPointerMotionOptions } from './../_shared/node-animation/to-pointer-motion-options.js';
import { usePrefersReducedMotion } from './../_shared/use-prefers-reduced-motion.js';
import { findNodeById } from './../tiptap-editor/helpers/index.js';

/** Which family of the animation a preview should play. */
export type PreviewFamily = 'entrance' | 'loop' | 'pointer';

// An infinite preview would never settle `finished`, leaving the previewing
// signal stuck and toolbars frozen in place — two rounds show the loop and stop.
const PREVIEW_LOOP_ITERATIONS = 2;

// Pointer effects have no timeline to play — the preview drives the instance's
// progress along one ellipse around the rest point (as if the cursor circled the
// node), then settles back to center and releases after the CSS transition.
const POINTER_SWEEP_DURATION = 1500;
const POINTER_SWEEP_RADIUS = 0.35;
// The settle waits out the effect's own transition, which Velocity makes anything from 0 to 5s
// — a fixed wait would `cancel()` mid-transition on the slow end, snapping the node back to
// rest and previewing something the viewer never plays. Just enough slack for the last frame.
const POINTER_SWEEP_SETTLE_BUFFER = 100;

/** Whatever is currently previewing — an AnimationGroup or a pointer sweep. */
type PreviewHandle = { cancel: () => void };

// The sweep's transform overhangs the node's box; on a LAST node that overhang joins the
// scrollable overflow of whatever scrolls the editor (`.custom_editor` when maxHeight is
// set, else the host page) and pumps its scrollbar for the whole sweep. Clipping the
// editing surface (view.dom) stops that propagation one level below the scroller: it is
// an ancestor of every previewed node and never a scroll container itself, so — unlike
// clipping the scroller — touching its overflow can't reset a scroll position. The clip
// is hard, no `overflow-clip-margin`: scrollable overflow excludes only content actually
// clipped away, so a margin re-admits exactly the scroll growth it lets paint (mirrors
// the viewer's scope-root rule, see node-animations.tsx). Transient inline rather than a
// stylesheet rule: a permanent clip would cut ProseMirror widgets that legitimately
// overflow. Per-property, never cssText — ProseMirror owns other inline styles on
// view.dom.
const applyPreviewOverflowClip = (dom: HTMLElement): (() => void) => {
  const previousOverflow = dom.style.getPropertyValue('overflow');
  dom.style.setProperty('overflow', 'clip');
  return () => {
    if (previousOverflow) {
      dom.style.setProperty('overflow', previousOverflow);
    } else {
      dom.style.removeProperty('overflow');
    }
  };
};

/**
 * Plays entrance, loop and mouse previews on the selected node's real DOM. WAAPI
 * and inline-transform mutations touch no attributes or DOM structure, so
 * ProseMirror's editing surface stays stable. The motion runtime loads on first
 * panel mount via dynamic import — editors without an open panel never pay for it.
 */
export const useAnimationPreview = (nodeId: string) => {
  const { adapter } = useContext(EditorContext);
  const prefersReducedMotion = usePrefersReducedMotion();
  const handleRef = useRef<PreviewHandle | null>(null);
  // Separate from PreviewHandle: the loop/entrance path stores motion's AnimationGroup in
  // handleRef directly, and the `handleRef.current === group` identity checks below are
  // load-bearing supersede semantics a wrapper would break.
  const restoreOverflowClipRef = useRef<(() => void) | null>(null);
  const disposedRef = useRef(false);

  // starts loading when the panel opens, so it's warm by the first pick
  const runtimePromise = useMemo(() => import('./../_shared/node-animation/motion-runtime.js'), []);

  // cancels any in-flight preview and clears the shared "is previewing" signal —
  // floating toolbars read that signal to pause their position tracking while a
  // preview is live, since they'd otherwise chase the animating node's bounding
  // rect every frame
  const cancelCurrent = () => {
    handleRef.current?.cancel();
    handleRef.current = null;
    restoreOverflowClipRef.current?.();
    restoreOverflowClipRef.current = null;
    setAnimationPreviewing(adapter.tiptapEditor, false);
  };

  useEffect(() => {
    disposedRef.current = false;
    return () => {
      disposedRef.current = true;
      cancelCurrent();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const stop = () => cancelCurrent();

  const play = async (animation: Animation, family: PreviewFamily = 'entrance') => {
    if (prefersReducedMotion) {
      return;
    }
    const { getEntranceAnimation, getLoopAnimation, getPointerAnimation } = await runtimePromise;
    if (disposedRef.current) {
      return;
    }
    // re-resolve the element on every play — React node views may remount
    // after attr writes, so a cached element could be stale
    const tr = adapter.tiptapEditor.view.state.tr;
    const [nodeWithPos] = findNodeById(tr, nodeId) ?? [];
    const element =
      nodeWithPos && (adapter.tiptapEditor.view.nodeDOM(nodeWithPos.pos) as HTMLElement | null);
    if (!element) {
      return;
    }
    cancelCurrent();

    if (family === 'pointer') {
      const instance = getPointerAnimation(element, animation);
      if (!instance) {
        return;
      }
      // the same resolution the runtime plays (stored ?? the effect's classic default)
      const settleMs =
        (toPointerMotionOptions(animation)?.transitionDuration ?? 0) + POINTER_SWEEP_SETTLE_BUFFER;
      let frame = 0;
      let settleTimer: ReturnType<typeof setTimeout> | null = null;
      const handle: PreviewHandle = {
        cancel: () => {
          if (frame) {
            cancelAnimationFrame(frame);
          }
          if (settleTimer) {
            clearTimeout(settleTimer);
          }
          instance.cancel();
        },
      };
      // Pointer previews only: entrance/loop travel overhangs just transiently, and a
      // hard clip would visibly cut it — same axis-of-trade as the viewer's pointer-only
      // scope rule. Applied only once a playable instance exists — an earlier apply
      // would dangle on the no-instance return above, with nothing left to restore it.
      restoreOverflowClipRef.current = applyPreviewOverflowClip(adapter.tiptapEditor.view.dom);
      handleRef.current = handle;
      setAnimationPreviewing(adapter.tiptapEditor, true);
      const start = performance.now();
      const tick = (now: number) => {
        // a newer preview owns the node now — this sweep's cancel already ran
        if (handleRef.current !== handle) {
          return;
        }
        const t = (now - start) / POINTER_SWEEP_DURATION;
        if (t >= 1) {
          instance.progress({ x: 0.5, y: 0.5 });
          // let the CSS transition settle the node back before releasing the signal
          settleTimer = setTimeout(() => handleRef.current === handle && cancelCurrent(), settleMs);
          return;
        }
        const angle = t * 2 * Math.PI;
        instance.progress({
          x: 0.5 + POINTER_SWEEP_RADIUS * Math.cos(angle),
          y: 0.5 + POINTER_SWEEP_RADIUS * Math.sin(angle),
        });
        frame = requestAnimationFrame(tick);
      };
      frame = requestAnimationFrame(tick);
      return;
    }

    const group =
      family === 'loop'
        ? getLoopAnimation(element, animation, { iterations: PREVIEW_LOOP_ITERATIONS })
        : getEntranceAnimation(element, animation);
    if (!group) {
      return;
    }
    handleRef.current = group;
    setAnimationPreviewing(adapter.tiptapEditor, true);
    // Motion's play() defers the real WAAPI start to `ready` (next frame) with no
    // cancelled-check in its continuation: a cancel landing in that window no-ops on the
    // still-idle animations, and the pending continuation then revives them — an orphaned
    // preview `cancelCurrent` can no longer reach, running alongside the next one. Start
    // only once ready, and only while this group is still the current preview, so a
    // superseded/stopped group never starts at all. The play() catch keeps an abandoned
    // preview's AbortError from surfacing as an unhandled rejection; `finished` below owns
    // the settle.
    group.ready
      .then(() => {
        if (handleRef.current === group) {
          group.play().catch(() => {});
        }
      })
      .catch(() => {});
    // only this group's own settle may clear the signal — an older, cancelled
    // group's rejection must not clobber a newer play
    group.finished.then(
      () => handleRef.current === group && cancelCurrent(),
      () => handleRef.current === group && cancelCurrent()
    );
  };

  return { play, stop };
};
