import React from 'react';

import type { EntranceEffectParams } from './../../_shared/node-animation/entrance-effects.js';

type Shape = NonNullable<EntranceEffectParams<'SHAPE'>['shape']>;

type ShapeIconProps = { width: string; height: string };

// Vendored from wix-private/santa-editor santa-editor-symbols/src/svg/motion/
// motion-shapes-{ellipse,circle,rectangle,rhombus}.svg — recolored via
// [data-ds-class] CSS, see animation-panel.scss. Upstream hardcodes fill="#2D3034"
// on three of the four (rhombus is missing it); dropped here since CSS owns the fill.
const shapeIcon =
  (children: React.ReactNode): React.FC<ShapeIconProps> =>
  ({ width, height }) => (
    <svg
      width={width}
      height={height}
      viewBox="0 0 51 51"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
    >
      {children}
    </svg>
  );

export const SHAPE_ICONS: Record<Shape, React.FC<ShapeIconProps>> = {
  ELLIPSE: shapeIcon(<ellipse data-ds-class="illus-clr-1" cx="25.5" cy="26" rx="10.5" ry="14" />),
  CIRCLE: shapeIcon(
    <rect data-ds-class="illus-clr-1" x="13" y="13" width="26" height="26" rx="13" />
  ),
  RECTANGLE: shapeIcon(<rect data-ds-class="illus-clr-1" x="14" y="14" width="24" height="24" />),
  DIAMOND: shapeIcon(
    <rect
      data-ds-class="illus-clr-1"
      x="25"
      y="11"
      width="20"
      height="20"
      transform="rotate(45 25 11)"
    />
  ),
};
